"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[1054],{2960(e){e.exports=JSON.parse('{"title":"Github \uc7ac\uad6c\uc131\ud558\uae30, RSC\uc640 CSS\ub85c","date":"2025-12-10","coverUrl":"/kudzu-based-bench/assets/notion/e91b42cd44f12d15.png","html":"<h1 data-notion-block-id=\\"2bde548d-8a8e-8095-91db-d016482437f7\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"2bfe548d-8a8e-8057-becf-e03feb71cdad\\" id=\\"2bfe548d-8a8e-8057-becf-e03feb71cdad\\">Github \uc7ac\uad6c\uc131\ud558\uae30, RSC\uc640 CSS\ub85c.</h2><a href=\\"https://wtbb.vercel.app/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://wtbb.vercel.app/</a><p data-notion-block-id=\\"2bfe548d-8a8e-803f-88e0-c37952de41db\\">\uae30\uc874 Github\uc758 Virtualization(ex. <a href=\\"https://sentry.engineering/blog/better-code-rendering-through-virtualization\\">Sentry\uc758 Virtualization \uac1c\uc120</a>)\ucc98\ub7fc, List Virtualization\uc744 \uc4f0\uc9c0 \uc54a\uace0, RSC\uc640 CSS\uc758 <code>content-visibility</code>\ub97c \uc0ac\uc6a9\ud574\uc11c \ucf54\ub4dc \ubdf0\ub97c \uc7ac\uad6c\uc131\ud558\ub294 \ubc29\uc2dd\uc744 \uc21c\ucc28\uc801\uc73c\ub85c \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uae30\uc874\uc5d0\ub294 \uc5b4\ub5bb\uac8c Virtualization\uc744 \uc9c4\ud589\ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 CSS\ub85c \uac00\uc0c1\ud654 \ud558\ub294 \ubc29\uc2dd\uc740 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \ubcf4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4. \ub610\ud55c <a href=\\"https://ones-to-watch.ethansup.net/news/post/117edf84-09ae-4b59-a977-3278116eb17f#4cfc7e8b-83bf-4c1d-bd47-241af33dc359\\"><code>content-visibility</code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/117edf84-09ae-4b59-a977-3278116eb17f#4cfc7e8b-83bf-4c1d-bd47-241af33dc359\\">\ub85c \uac00\uc0c1\ud654 \ub300\uc2e0\ud558\uae30</a>\ub098 <a href=\\"https://ones-to-watch.ethansup.net/news/post/224e548d-8a8e-8082-b2ce-cbe57644a859#228e548d-8a8e-80a1-8373-f51903e8f5e6\\">Virtualizing. \uc5b4\ub5a4 \uac83\uc774\uace0 \uc5b4\ub5a4 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc788\uc744\uae4c</a>\ub3c4 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2bfe548d-8a8e-80d9-9daf-fbdd34207391\\" id=\\"2bfe548d-8a8e-80d9-9daf-fbdd34207391\\">Sonner \uc81c\uc791\uae30. \uadf8\ub9ac\uace0 \ub9c8\uc8fc\uce5c \ubb38\uc81c\ub4e4</h2><a href=\\"https://emilkowal.ski/ui/building-a-toast-component\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://emilkowal.ski/ui/building-a-toast-component</a><p data-notion-block-id=\\"2c3e548d-8a8e-80fe-a151-da53f89e70b1\\">\uc65c CSS\ub9cc\uc73c\ub85c Toast\ub97c \uad6c\ud604\ud560 \uc218 \uc5c6\uc5c8\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \ub514\ud14c\uc77c\uc744 \uc7a1\uc544\uc11c \uc0ac\uc6a9\uc790\ub4e4, \uadf8\ub9ac\uace0 \uac1c\ubc1c\uc790\ub4e4\uc744 \uc0ac\ub85c\uc7a1\uc558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub54c\ub85c\ub294 \ub514\ud14c\uc77c\uacfc \uc544\ub984\ub2e4\uc6b4(\uc5ec\uae30\uc120 \uc560\ub2c8\uba54\uc774\uc158\uc774 \ub418\uaca0\ub124\uc694) \ub514\uc790\uc778\uc774 \uc0ac\uc6a9\uc790\ub97c \uc0ac\ub85c\uc7a1\ub294 \uac83\uc744 \uc54c\uac8c\ub418\uc5c8\ub124\uc694. \uadf8\ub9ac\uace0 \uadf8\uac83\uc744 \uc5b4\ub5bb\uac8c \uad6c\ud604\ud558\ub294\uc9c0 \uae4c\uc9c0\uc694!</p><h2 data-notion-block-id=\\"2c2e548d-8a8e-80f7-bc3a-d136f6cbc527\\" id=\\"2c2e548d-8a8e-80f7-bc3a-d136f6cbc527\\">\ub9ac\uc561\ud2b8\uc5d0 \ub9de\uac8c, \ud6c5\ub3c4 \ubc14\ub00c\uc5b4\uc57c \ud569\ub2c8\ub2e4</h2><a href=\\"https://allthingssmitty.com/2025/12/01/react-has-changed-your-hooks-should-too/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://allthingssmitty.com/2025/12/01/react-has-changed-your-hooks-should-too/</a><p data-notion-block-id=\\"2c2e548d-8a8e-8003-ab59-fd0efe6aaaf7\\">\uac04\ub2e8\ud558\uac8c, useEffect\ub9d0\uace0\ub3c4, React 18/19\ubc84\uc804\uc73c\ub85c \ubc14\ub00c\uba74\uc11c, \ub2e4\uc591\ud55c \ud6c5\uc744 \uc0ac\uc6a9\ud560 \uc904 \uc54c\uc544\uc57c \ud55c\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/211e548d-8a8e-8076-80cd-cabfc20df523#212e548d-8a8e-8093-9b0a-f09a93463cf7\\"><code>useSyncExternalStore</code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/211e548d-8a8e-8076-80cd-cabfc20df523#212e548d-8a8e-8093-9b0a-f09a93463cf7\\">\ub294 \uaf64\ub098 \uc0ac\uc6a9\ud558\uae30 \uc27d\ub2e4</a>\ub098 <a href=\\"https://ones-to-watch.ethansup.net/news/post/1cfe548d-8a8e-8030-818c-eea9d093d4aa#1d4e548d-8a8e-8049-8d15-e702077d34a3\\"><code>useState</code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/1cfe548d-8a8e-8030-818c-eea9d093d4aa#1d4e548d-8a8e-8049-8d15-e702077d34a3\\">\ubcf4\ub2e4 \uc0c1\ud0dc\uc5d0 \uce5c\ud574\uc9c0\uae30</a>\uc640 \uac19\uc774 \uc5ec\ub7ec \ud6c5\uc774\ub098 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \uae30\ubcf8 \uc18c\uc591\uc774 \ub418\uc5b4\uc57c \ub420 \uc218\ub3c4 \uc788\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2bde548d-8a8e-8052-ac72-fec3ac2d5932\\" id=\\"2bde548d-8a8e-8052-ac72-fec3ac2d5932\\">Micro Frontend\ub97c \ub3c4\uc785\ud558\uae30\ub85c \ub9c8\uc74c\uba39\uc5c8\ub2e4</h2><a href=\\"https://www.youtube.com/watch?v=J_y4-haLf8s\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=J_y4-haLf8s</a><p data-notion-block-id=\\"2c4e548d-8a8e-809a-ab7f-e89794d6b505\\">F1\ud300\uc5d0\uc11c \ubaa8\ub180\ub9ac\uc2dd \uad6c\uc870\uc5d0\uc11c MFE\ub97c \uc65c \uc804\ud658\ud558\uac8c \ub418\uc5c8\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c <a href=\\"https://lucamezzalira.com/2019/12/22/micro-frontends-decisions-framework/\\">\uc758\uc0ac\uacb0\uc815 \ud504\ub808\uc784\uc6cc\ud06c</a>\ub97c \uae30\ubc18\uc73c\ub85c \uc5b4\ub5bb\uac8c \uc810\uc9c4\uc801\uc73c\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ud588\ub294\uc9c0, \uacb0\uacfc\ub294 \uc5b4\ub560\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uc601\uc0c1\uc785\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c MFE\uc5d0 \uad00\uc2ec\uc774 \uc788\uc73c\uc2dc\ub2e4\uba74, <a href=\\"https://www.youtube.com/watch?v=R2Ydq5E_8ts\\">MFE \uc548\ud2f0\ud328\ud134</a> \uc601\uc0c1\uc5d0\uc11c\uc758 MFE \ub3c4\uc785 \uc2dc\uc5d0 \uc5b4\ub5a4 \uacb0\uc815\uc744 \ud53c\ud574\uc57c \ud558\ub294\uc9c0\ub3c4 \uac19\uc774 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2bfe548d-8a8e-8055-bfbc-dcc4228f5bbc\\" id=\\"2bfe548d-8a8e-8055-bfbc-dcc4228f5bbc\\">\uc815\ub9d0\ub85c MSA\uac00 \ud544\uc694\ud55c\uac00?</h2><a href=\\"https://www.docker.com/blog/do-you-really-need-microservices/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.docker.com/blog/do-you-really-need-microservices/</a><p data-notion-block-id=\\"2c2e548d-8a8e-806c-9e48-c55171ed645f\\">\uc704\uc758 \uc0ac\ub840\uc640 \ubc18\ub300\ub85c, 90%\uc758 \uc870\uc9c1\uc740 \uc798 \uc124\uacc4\ub41c \ubaa8\ub180\ub9ac\uc2dd \uc544\ud0a4\ud14d\uccd0\ub85c \ucda9\ubd84\ud558\uba70, MSA\uc758 \ub2e8\uc810, \uadf8\ub9ac\uace0 \ud0c8 MSA \uc0ac\ub840, \uadf8\ub9ac\uace0 \ub300\uc548\uc744 \uc81c\uc2dc\ud569\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c <a href=\\"https://ones-to-watch.ethansup.net/news/post/5ca5c5cc-3d5f-4c16-bb30-9df937ea2199#30607141-7ac8-4086-95ad-482bf45ebf31\\">Micro Frontends\u2026?</a> \uae00\uc744 \uc77d\uc5b4\ubcf4\uc2dc\uba74 \uc7a5\ub2e8\uc810\uc744 \uc798 \uc870\uc728\ud574\uac00\uba70 \uae30\uc220\uc744 \ub3c4\uc785\ud560 \uc218 \uc788\uc744\uac81\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2c2e548d-8a8e-80c1-8921-e76badcb55ed\\" id=\\"2c2e548d-8a8e-80c1-8921-e76badcb55ed\\">NPM \ubcf4\uc548 \uac00\uc774\ub4dc: \ud328\ud0a4\uc9c0 \ubcf4\uc548</h2><a href=\\"https://snyk.io/fr/articles/npm-security-best-practices-shai-hulud-attack/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://snyk.io/fr/articles/npm-security-best-practices-shai-hulud-attack/</a><p data-notion-block-id=\\"2c3e548d-8a8e-80b6-9571-fd9a55837aa9\\">12\uac00\uc9c0 \uc911\uc694\ud55c \uae30\uc220\ub4e4\ub85c npm \uacf5\uae09\ub9dd \uacf5\uaca9\uc744 \ubc29\uc5b4\ud560 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c <a href=\\"https://ones-to-watch.ethansup.net/news/post/262e548d-8a8e-80eb-9e8b-cd0868f2c950#27be548d-8a8e-8017-a474-e98c3e77a1cb\\">\ud328\ud0a4\uc9c0 \uad00\ub9ac\uc790\ub97c \ud1b5\ud55c \uacf5\uae09\ub9dd \uacf5\uaca9 \ub300\ube44\ud558\uae30</a>\ub97c \ucc38\uc870\ud558\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2bfe548d-8a8e-803c-8485-d1d20256692d\\" id=\\"2bfe548d-8a8e-803c-8485-d1d20256692d\\">AI\uc640 AST\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158\ud558\uae30</h2><a href=\\"https://eliocapella.com/blog/ai-library-migration-guide/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://eliocapella.com/blog/ai-library-migration-guide/</a><p data-notion-block-id=\\"2c5e548d-8a8e-8027-a545-f27c85bf335a\\">AI\ub85c \uc0dd\uc0b0\uc131 \ud5a5\uc0c1\uc744 \uc5b4\ub5bb\uac8c \uc774\ub04c\uc5b4\ub0c8\ub294\uc9c0, \ub2e8\uacc4\ubcc4\ub85c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. AST \ub0b4\uc6a9\uc740 jscodeshift \ub0b4\uc6a9\ubc16\uc5d0 \uc5c6\uc9c0\ub9cc, \uadf8\ub798\ub3c4 \ud574\uacb0 \uc811\uadfc\ubc95\uc740 \uc218\ub9ce\uc740 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ubc29\uc2dd\uc5d0 \uc801\uc6a9\ud574\ubcfc \uc218 \uc788\uc73c\ubbc0\ub85c \uad00\uc2ec\uc788\uac8c \ubcf4\uc2dc\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"2bde548d-8a8e-807b-ba06-dda19544a632\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"2bfe548d-8a8e-800d-b6eb-d163e13dc54c\\" id=\\"2bfe548d-8a8e-800d-b6eb-d163e13dc54c\\">RSC\uc5d0 \uc2ec\uac01\ud55c \ubcf4\uc548 \uc774\uc288\uac00 \uc788\uc5c8\ub2e4.</h2><a href=\\"https://react.dev/blog/2025/12/03/critical-security-vulnerability-in-react-server-components\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://react.dev/blog/2025/12/03/critical-security-vulnerability-in-react-server-components</a><p data-notion-block-id=\\"2bfe548d-8a8e-80c0-9318-d6a85d7849e1\\">Server Component\uc640 Server Action\uc5d0 \ud574\ub2f9\ud558\ub294 React Flight(\ub0b4\ubd80 \uc774\ub984) \ud504\ub85c\ud1a0\ucf5c\uc758 \uc9c1\ub82c\ud654/\uc5ed\uc9c1\ub82c\ud654 \uc774\uc288\uac00 \uc788\uc5c8\ub2e4\uace0 \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2c3e548d-8a8e-8061-b29f-e47f9ab743e5\\" id=\\"2c3e548d-8a8e-8061-b29f-e47f9ab743e5\\">UX\ub294 \uae30\uc220\ubcf4\ub2e4 \uc555\ub3c4\uc801\uc778 \uc131\ub2a5\uc744 \ub0b8\ub2e4.</h2><a href=\\"https://eleganthack.com/ux-is-your-moat-and-youre-ignoring-it/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://eleganthack.com/ux-is-your-moat-and-youre-ignoring-it/</a><p data-notion-block-id=\\"2bfe548d-8a8e-8054-903d-fbac1df95365\\">\uc5ec\ub7ec\uac00\uc9c0 \uae30\uc0ac\uc640 \uc608\uc2dc\ub97c \ub4e4\uba74\uc11c UX\uac00 AI\uc758 \ubaa8\ub378 \uc131\ub2a5, \ucf58\ud150\uce20\ubcf4\ub2e4 \uc911\uc694\ud55c\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uadf8\ub7ec\uba74\uc11c AI \ud68c\uc0ac\uc5d0 \uc758\ubbf8\ud558\ub294 \ubc14\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4(\uadf8\ub0e5 \uc11c\ube44\uc2a4 \ud68c\uc0ac\uc5d0\ub3c4 \uc801\uc6a9\ub418\ub294 \ub9d0\uc774\uc5ec\uc11c, \ub3c4\uc6c0\uc774 \ub420 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4).</p><h2 data-notion-block-id=\\"2c2e548d-8a8e-8037-bcc6-de9af7952ea1\\" id=\\"2c2e548d-8a8e-8037-bcc6-de9af7952ea1\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \ub514\uc790\uc778\ud558\ub294 \ubc95</h2><a href=\\"https://tkdodo.eu/blog/designing-design-systems\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/designing-design-systems</a><p data-notion-block-id=\\"2bde548d-8a8e-8044-ac2e-c44d7ebe66cd\\">\uc88b\uc740 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc774 \ubb34\uc5c7\uc778\uc9c0\uc5d0 \ub300\ud55c \uc6d0\uce59\uc744 \uac04\ub2e8\ud558\uac8c \ub098\uc5f4\ud574\ub193\uc740 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2bfe548d-8a8e-8088-bf66-f9dfc8152e37\\" id=\\"2bfe548d-8a8e-8088-bf66-f9dfc8152e37\\"><code>&#x3C;Activity></code>\ub85c \uc0c1\ud0dc \ubcf4\uad00\ud558\uae30</h2><a href=\\"https://www.epicreact.dev/use-react-activity-to-preload-a-video-y2lmw\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.epicreact.dev/use-react-activity-to-preload-a-video-y2lmw</a><h2 data-notion-block-id=\\"2c3e548d-8a8e-8061-a8bd-f7e82ce9c4e8\\" id=\\"2c3e548d-8a8e-8061-a8bd-f7e82ce9c4e8\\">\uadf8\ub798\uc11c Baseline\uc740 \uc5b4\ub5bb\uac8c \uc368\uc57c\ud574\uc694?</h2><a href=\\"https://web.dev/series/baseline-in-action\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://web.dev/series/baseline-in-action</a><p data-notion-block-id=\\"2c3e548d-8a8e-80ea-8967-dfdf323fa983\\">Baseline\uc73c\ub85c \uc548\uc815\ub41c \uae30\uc220\ub4e4\uc744 \uc0ac\uc6a9\ud574\uc11c \uc5b4\ub5bb\uac8c \uc2e4 \uc0ac\uc6a9\uc744 \ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\ub4e4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2bfe548d-8a8e-80ee-b36b-cee6b78140aa\\" id=\\"2bfe548d-8a8e-80ee-b36b-cee6b78140aa\\">\ud398\uc774\uc9c0 \ud328\ud134\uc5d0\uc11c \uc811\uadfc\uc131 \ucc59\uae30\uae30</h2><a href=\\"https://www.tempertemper.net/blog/an-accessible-pagination-pattern-or-two\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.tempertemper.net/blog/an-accessible-pagination-pattern-or-two</a><p data-notion-block-id=\\"2c4e548d-8a8e-808c-8b42-f289f1dc0ed1\\">\ub450\uac00\uc9c0 \ud398\uc774\uc9c0 \ud328\ud134\uc5d0\uc11c \uc811\uadfc\uc131\uc744 \uc5b4\ub5bb\uac8c \ucc59\uaca8\uc57c \ud558\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4</p><h2 data-notion-block-id=\\"2c4e548d-8a8e-8039-8593-e2a655bda9ac\\" id=\\"2c4e548d-8a8e-8039-8593-e2a655bda9ac\\"><code>popover</code>\uc640 <code>&#x3C;dialog></code>\uac00 \ub098\uc654\uc5b4\uc694. \uadfc\ub370 \ubb50\uac00 \uc704\uc5d0 \ubc30\uce58\ub418\uc694?</h2><a href=\\"https://htmhell.dev/adventcalendar/2025/1/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://htmhell.dev/adventcalendar/2025/1/</a><p data-notion-block-id=\\"2c4e548d-8a8e-806a-86b3-e2888f351b0e\\">\ucd5c\uc2e0 \uae30\ub2a5\uc778 <code>popover</code>\uc640 <code>&#x3C;dialog></code>\ub97c \ub3d9\uc2dc\uc5d0 \uc0ac\uc6a9\ud588\uc744 \ub54c\uc758 \uc811\uadfc\uc131 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \ubc29\uc2dd\uc744 \uc54c\ub824\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2bfe548d-8a8e-800a-ab38-eebd6060e3ba\\" id=\\"2bfe548d-8a8e-800a-ab38-eebd6060e3ba\\">RN\uc5d0\uc11c \uc778\uc99d\ub41c Deep Link \ub2e4\ub8e8\uae30</h2><a href=\\"https://www.callstack.com/blog/deep-links-with-authentication-in-react-navigation\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.callstack.com/blog/deep-links-with-authentication-in-react-navigation</a><h1 data-notion-block-id=\\"2bde548d-8a8e-8085-9851-c6c2a84d7314\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://prettier.io/blog/2025/11/27/3.7.0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://prettier.io/blog/2025/11/27/3.7.0</a><p data-notion-block-id=\\"2c2e548d-8a8e-80ca-a725-d69ee84b96e2\\">Prettier 3.7\ubc84\uc804\uc774 \ub098\uc624\uba74\uc11c TypeScript \ud3ec\ub9e4\ud305\uc774 \ud55c\uce35 \ub354 \uc77c\uad00\uc801\uc73c\ub85c \ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://voidzero.dev/posts/announcing-vite-8-beta\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://voidzero.dev/posts/announcing-vite-8-beta</a><p data-notion-block-id=\\"2c2e548d-8a8e-80eb-a6b4-c20012b2bdc7\\">Vite 8 \ubca0\ud0c0\uac00 \ub098\uc624\uba74\uc11c Rolldown \uae30\ubc18 Vite\uac00 \uacf5\uc2dd\ud654\ub418\ub824\ub294 \uc6c0\uc9c1\uc784\uc774 \ud55c\uce35 \ub354 \uac15\ud654\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://devblogs.microsoft.com/typescript/progress-on-typescript-7-december-2025/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://devblogs.microsoft.com/typescript/progress-on-typescript-7-december-2025/</a><p data-notion-block-id=\\"2bfe548d-8a8e-80a9-b10e-dc41c9237da9\\">TypeScript 7(tsgo)\uc758 \uac1c\ubc1c \uc18c\uc2dd\uacfc TypeScript 6\ubc84\uc804\uc740 \uc5b4\ub5bb\uac8c \ub420 \uac83\uc778\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://oxc.rs/blog/2025-12-01-oxfmt-alpha.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://oxc.rs/blog/2025-12-01-oxfmt-alpha.html</a><p data-notion-block-id=\\"2bfe548d-8a8e-80fb-9cfc-ced6d7a80b74\\">oxc \uac00\uc871 \uc911 \ud558\ub098\uc778 oxc \ud3ec\ub9e4\ud130\uac00 \uc54c\ud30c\ubc84\uc804 \ucd9c\uc2dc\ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://www.epicreact.dev/react-routers-take-on-react-server-components-4bj7q\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.epicreact.dev/react-routers-take-on-react-server-components-4bj7q</a><p data-notion-block-id=\\"2bfe548d-8a8e-80c9-bff3-f79929fb70f2\\">React router\uc5d0\uc11c \uc774\uc81c RSC\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://www.projectwallace.com/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.projectwallace.com/</a><p data-notion-block-id=\\"2bfe548d-8a8e-804e-a797-e5178b763b4d\\">\ud398\uc774\uc9c0\ub97c \uc785\ub825\ud558\uba74 CSS\ub97c \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud588\ub098, \uc77c\uad00\uc131\uc788\uac8c \uc0ac\uc6a9\ud588\ub098 \ubcf4\uc5ec\uc8fc\ub294 \uc11c\ube44\uc2a4\uc785\ub2c8\ub2e4.</p><a href=\\"https://blog.swmansion.com/rnrepo-faster-react-native-builds-through-prebuilt-artifacts-004903b5e510\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.swmansion.com/rnrepo-faster-react-native-builds-through-prebuilt-artifacts-004903b5e510</a><p data-notion-block-id=\\"2c3e548d-8a8e-8019-b644-c10489466166\\">React Native\uc758 \ube4c\ub4dc \uc18d\ub3c4 \uac1c\uc120\uc744 \uc704\ud574\uc11c Prebuilt Artifacts \uae30\ub2a5\uc744 \uc0ac\uc6a9\ud574\uc11c \ube4c\ub4dc\uc2dc\uac04\uc744 \ub2e8\ucd95\ud558\ub294 rnrepo\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);